class SectionErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidCatch(error) {
    console.error("Section render error", error);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="ed-note err" style={{ marginTop: 16 }}>
          Nepavyko atvaizduoti šios dalies. Atnaujinkite puslapį ir bandykite dar kartą.
        </div>
      );
    }

    return this.props.children;
  }
}

function StyledConfirmDialog({ dialog, onResolve }) {
  if (!dialog) return null;

  return (
    <div
      role="presentation"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onResolve(false);
      }}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 4000,
        display: "grid",
        placeItems: "center",
        padding: 20,
        background: "rgba(16,36,56,.62)",
      }}
    >
      <section
        role="dialog"
        aria-modal="true"
        aria-labelledby="styled-confirm-title"
        style={{
          width: "min(520px,100%)",
          background: "#fff",
          borderRadius: 18,
          padding: 22,
          color: "#102438",
          boxShadow: "0 26px 80px rgba(16,36,56,.25)",
        }}
      >
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16 }}>
          <div>
            {dialog.eyebrow && <div className="eyebrow" style={{ marginBottom: 7 }}>{dialog.eyebrow}</div>}
            <h2 id="styled-confirm-title" style={{ margin: 0, fontSize: 22 }}>
              {dialog.title || "Patvirtinkite veiksmą"}
            </h2>
          </div>
          <button
            type="button"
            aria-label="Uždaryti"
            onClick={() => onResolve(false)}
            style={{
              border: 0, background: "#f1f4f6", borderRadius: 10, width: 40, height: 40,
              display: "grid", placeItems: "center", color: "#102438", flex: "0 0 auto",
            }}
          >
            <CloseMark />
          </button>
        </div>
        <p style={{ margin: "16px 0 0", color: "#607180", lineHeight: 1.55 }}>{dialog.message}</p>
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 9, marginTop: 22, flexWrap: "wrap" }}>
          {!dialog.hideCancel && (
            <button
              type="button"
              onClick={() => onResolve(false)}
              style={{ minHeight: 42, padding: "9px 16px", border: "1px solid #d7e1e7", borderRadius: 10, background: "#fff", color: "#102438", fontWeight: 800 }}
            >
              {dialog.cancelLabel || "Atšaukti"}
            </button>
          )}
          <button
            type="button"
            onClick={() => onResolve(true)}
            style={{ minHeight: 42, padding: "9px 16px", border: 0, borderRadius: 10, background: dialog.danger ? "#b64d2a" : "#f08a28", color: "#fff", fontWeight: 850 }}
          >
            {dialog.confirmLabel || "Patvirtinti"}
          </button>
        </div>
      </section>
    </div>
  );
}

function useStyledConfirm() {
  const [dialog, setDialog] = useState(null);
  const resolverRef = useRef(null);

  const askConfirm = (config) => new Promise((resolve) => {
    resolverRef.current = resolve;
    setDialog(config);
  });

  const resolveConfirm = (value) => {
    const resolver = resolverRef.current;
    resolverRef.current = null;
    setDialog(null);
    resolver?.(value);
  };

  return { dialog, askConfirm, resolveConfirm };
}

function normalizeLithuanianMobilePhone(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const digits = raw.replace(/\D/g, "");

  if (/^3706\d{7}$/.test(digits)) return `+${digits}`;
  if (/^06\d{7}$/.test(digits)) return `+370${digits.slice(1)}`;
  if (/^6\d{7}$/.test(digits)) return `+370${digits}`;
  return "";
}

function isValidLithuanianMobilePhone(value) {
  return Boolean(normalizeLithuanianMobilePhone(value));
}

function RoundedSelect({ value, options, disabled, onChange, className = "ed-select", ariaLabel = "Pasirinkimas", buttonRef = null }) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef(null);
  const triggerRef = useRef(null);
  const selected = options.find((option) => option.value === value);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event) => {
      if (!containerRef.current?.contains(event.target)) setOpen(false);
    };
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  return (
    <div ref={containerRef} style={{ position: "relative", width: "100%", minWidth: 0 }}>
      <button
        ref={(node) => {
          triggerRef.current = node;
          if (typeof buttonRef === "function") buttonRef(node);
          else if (buttonRef) buttonRef.current = node;
        }}
        type="button"
        className={className}
        disabled={disabled}
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown") {
            event.preventDefault();
            setOpen(true);
            requestAnimationFrame(() => containerRef.current?.querySelector('[role="option"]')?.focus());
          }
        }}
        style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", textAlign: "left", background: "#fff", borderRadius: 12, cursor: disabled ? "not-allowed" : "pointer" }}
      >
        <span style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{selected?.label || "Pasirinkite"}</span>
        <span aria-hidden="true" style={{ marginLeft: 12 }}>⌄</span>
      </button>
      {open && !disabled && (
        <div role="listbox" aria-label={ariaLabel} style={{ position: "absolute", zIndex: 50, top: "calc(100% + 6px)", left: 0, right: 0, maxHeight: 240, overflowY: "auto", padding: 5, background: "#fff", border: "1px solid #dfe7ed", borderRadius: 12, boxShadow: "0 14px 35px rgba(16,36,56,.14)" }}>
          {options.map((option) => (
            <button
              key={option.value}
              type="button"
              role="option"
              aria-selected={option.value === value}
              onClick={() => { onChange(option.value); setOpen(false); triggerRef.current?.focus(); }}
              onKeyDown={(event) => {
                if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
                event.preventDefault();
                const buttons = [...containerRef.current.querySelectorAll('[role="option"]')];
                const next = buttons.indexOf(event.currentTarget) + (event.key === "ArrowDown" ? 1 : -1);
                buttons[(next + buttons.length) % buttons.length]?.focus();
              }}
              style={{ display: "block", width: "100%", padding: "10px 12px", textAlign: "left", border: 0, borderRadius: 8, background: option.value === value ? "#fff1e5" : "#fff", color: "#102438", font: "inherit", cursor: "pointer" }}
            >
              {option.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function parseDateValue(value) {
  const match = String(value || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12, 0, 0, 0);
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatDateInputValue(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return "";
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function formatDateDisplay(value, placeholder = "Pasirinkite datą") {
  const date = parseDateValue(value);
  if (!date) return placeholder;
  return new Intl.DateTimeFormat("lt-LT", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(date);
}

function RoundedDateSelect({
  value,
  disabled,
  onChange,
  ariaLabel = "Data",
  align = "left",
  className = "ed-input wd-date-trigger",
  placeholder = "Pasirinkite datą",
  allowClear = true,
}) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef(null);
  const triggerRef = useRef(null);
  const selectedDate = parseDateValue(value);
  const initialDate = selectedDate || new Date();
  const [viewMonth, setViewMonth] = useState(
    () => new Date(initialDate.getFullYear(), initialDate.getMonth(), 1, 12)
  );

  useEffect(() => {
    if (!open) return;
    const next = parseDateValue(value) || new Date();
    setViewMonth(new Date(next.getFullYear(), next.getMonth(), 1, 12));
  }, [open, value]);

  useEffect(() => {
    if (!open) return;
    const closeOutside = (event) => {
      if (!containerRef.current?.contains(event.target)) setOpen(false);
    };
    const closeOnEscape = (event) => {
      if (event.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("pointerdown", closeOutside);
    document.addEventListener("keydown", closeOnEscape);
    return () => {
      document.removeEventListener("pointerdown", closeOutside);
      document.removeEventListener("keydown", closeOnEscape);
    };
  }, [open]);

  const year = viewMonth.getFullYear();
  const month = viewMonth.getMonth();
  const firstDay = new Date(year, month, 1, 12);
  const mondayOffset = (firstDay.getDay() + 6) % 7;
  const gridStart = new Date(year, month, 1 - mondayOffset, 12);
  const todayValue = formatDateInputValue(new Date());
  const monthLabel = new Intl.DateTimeFormat("lt-LT", {
    month: "long",
    year: "numeric",
  }).format(viewMonth);
  const dayLabels = ["Pr", "An", "Tr", "Kt", "Pn", "Št", "Sk"];

  return (
    <div ref={containerRef} style={{ position: "relative", width: "100%", minWidth: 0 }}>
      <button
        ref={triggerRef}
        type="button"
        className={className}
        disabled={disabled}
        aria-label={ariaLabel}
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
      >
        <span style={!value ? { color: "#8a98a6" } : undefined}>
          {formatDateDisplay(value, placeholder)}
        </span>
        <span aria-hidden="true" className="wd-date-icon">▦</span>
      </button>

      {open && !disabled && (
        <div
          role="dialog"
          aria-label={ariaLabel}
          className="wd-date-popover"
          style={align === "right" ? { right: 0 } : { left: 0 }}
        >
          <div className="wd-date-head">
            <b>{monthLabel}</b>
            <div className="wd-date-nav">
              <button
                type="button"
                aria-label="Ankstesnis mėnuo"
                onClick={() => setViewMonth(new Date(year, month - 1, 1, 12))}
              >
                ‹
              </button>
              <button
                type="button"
                aria-label="Kitas mėnuo"
                onClick={() => setViewMonth(new Date(year, month + 1, 1, 12))}
              >
                ›
              </button>
            </div>
          </div>

          <div className="wd-date-weekdays" aria-hidden="true">
            {dayLabels.map((day) => <span key={day}>{day}</span>)}
          </div>

          <div className="wd-date-grid">
            {Array.from({ length: 42 }, (_, index) => {
              const date = new Date(gridStart);
              date.setDate(gridStart.getDate() + index);
              const optionValue = formatDateInputValue(date);
              const outside = date.getMonth() !== month;
              const selected = optionValue === value;
              const today = optionValue === todayValue;
              return (
                <button
                  key={optionValue}
                  type="button"
                  className={[outside ? "outside" : "", selected ? "selected" : "", today ? "today" : ""].filter(Boolean).join(" ")}
                  aria-label={new Intl.DateTimeFormat("lt-LT", { year: "numeric", month: "long", day: "numeric" }).format(date)}
                  aria-pressed={selected}
                  onClick={() => {
                    onChange(optionValue);
                    setOpen(false);
                    triggerRef.current?.focus();
                  }}
                >
                  {date.getDate()}
                </button>
              );
            })}
          </div>

          <div className="wd-date-actions">
            {allowClear ? (
              <button
                type="button"
                onClick={() => {
                  onChange("");
                  setOpen(false);
                  triggerRef.current?.focus();
                }}
              >
                Išvalyti
              </button>
            ) : <span />}
            <button
              type="button"
              onClick={() => {
                onChange(todayValue);
                setOpen(false);
                triggerRef.current?.focus();
              }}
            >
              Šiandien
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function RoundedTimeSelect({ value, disabled, onChange, ariaLabel, align = "left", className = "wd-time wd-time-trigger", placeholder = "Pasirinkite laiką", minTime = null, maxTime = null, buttonRef = null }) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef(null);
  const triggerRef = useRef(null);
  const hasValue = Boolean(value);
  const [hour = "08", minute = "00"] = String(value || "08:00").split(":");

  const timeToMinutes = (time) => {
    if (!time) return null;
    const [h, m] = String(time).split(":").map(Number);
    if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
    return h * 60 + m;
  };

  const isAllowedTime = (time) => {
    const minutes = timeToMinutes(time);
    const minMinutes = timeToMinutes(minTime);
    const maxMinutes = timeToMinutes(maxTime);
    if (minutes === null) return false;
    if (minMinutes !== null && minutes < minMinutes) return false;
    if (maxMinutes !== null && minutes > maxMinutes) return false;
    return true;
  };

  useEffect(() => {
    if (!open) return;
    const closeOutside = (event) => {
      if (!containerRef.current?.contains(event.target)) setOpen(false);
    };
    const closeOnEscape = (event) => {
      if (event.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("pointerdown", closeOutside);
    document.addEventListener("keydown", closeOnEscape);
    return () => {
      document.removeEventListener("pointerdown", closeOutside);
      document.removeEventListener("keydown", closeOnEscape);
    };
  }, [open]);

  const hourOptions = Array.from({ length: 24 }, (_, index) =>
    String(index).padStart(2, "0")
  );
  const minuteOptions = Array.from({ length: 12 }, (_, index) =>
    String(index * 5).padStart(2, "0")
  );

  return (
    <div ref={containerRef} style={{ position: "relative", width: "100%", minWidth: 0 }}>
      <button
        ref={(node) => {
          triggerRef.current = node;
          if (typeof buttonRef === "function") buttonRef(node);
          else if (buttonRef) buttonRef.current = node;
        }}
        type="button"
        className={className}
        disabled={disabled}
        aria-label={ariaLabel}
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
      >
        <span style={!hasValue ? { color: "#8a98a6" } : undefined}>
          {hasValue ? `${hour}:${minute}` : placeholder}
        </span>
        <span aria-hidden="true">◷</span>
      </button>

      {open && !disabled && (
        <div
          role="dialog"
          aria-label={ariaLabel}
          className="wd-time-popover wd-time-popover-compact"
          style={align === "right" ? { right: 0 } : { left: 0 }}
        >
          <div className="wd-time-compact-section">
            <b>Valandos</b>
            <div className="wd-time-compact-grid hours">
              {hourOptions.map((option) => {
                const candidate = `${option}:${minute}`;
                const optionDisabled = !isAllowedTime(candidate);
                return (
                  <button
                    key={option}
                    type="button"
                    className={option === hour ? "selected" : ""}
                    disabled={optionDisabled}
                    onClick={() => {
                      if (optionDisabled) return;
                      onChange(`${option}:${minute}`);
                    }}
                  >
                    {option}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="wd-time-compact-section">
            <b>Minutės</b>
            <div className="wd-time-compact-grid minutes">
              {minuteOptions.map((option) => {
                const candidate = `${hour}:${option}`;
                const optionDisabled = !isAllowedTime(candidate);
                return (
                  <button
                    key={option}
                    type="button"
                    className={option === minute ? "selected" : ""}
                    disabled={optionDisabled}
                    onClick={() => {
                      if (optionDisabled) return;
                      onChange(`${hour}:${option}`);
                      setOpen(false);
                      triggerRef.current?.focus();
                    }}
                  >
                    {option}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

