function localDateISO(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function nextSevenDays() {
  return Array.from({ length: 7 }, (_, i) => {
    const date = new Date();
    date.setHours(12, 0, 0, 0);
    date.setDate(date.getDate() + i);
    return {
      iso: localDateISO(date),
      weekday: new Intl.DateTimeFormat("lt-LT", { weekday: "short" }).format(date),
      label: new Intl.DateTimeFormat("lt-LT", { day: "2-digit", month: "2-digit" }).format(date),
    };
  });
}

function formatNetPay(amount, unit) {
  const value = Number(amount);
  if (!Number.isFinite(value) || value <= 0) return "Atlygis nenurodytas";
  const formatted = Number.isInteger(value)
    ? String(value)
    : value.toLocaleString("lt-LT", { maximumFractionDigits: 2 });
  return unit === "day"
    ? `${formatted} € į rankas / dieną`
    : `${formatted} € į rankas / val.`;
}

function formatWorkedMinutes(minutes) {
  const total = Math.max(0, Number(minutes) || 0);
  const hours = Math.floor(total / 60);
  const mins = total % 60;
  if (!hours) return `${mins} min.`;
  if (!mins) return `${hours} val.`;
  return `${hours} val. ${mins} min.`;
}

function jobEndMoment(job) {
  if (!job?.work_date) return null;
  const end = (job.end_time || job.start_time || "23:59").slice(0, 5);
  const value = new Date(`${job.work_date}T${end}:00`);
  return Number.isNaN(value.getTime()) ? null : value;
}

function jobHasEnded(job) {
  const end = jobEndMoment(job);
  return end ? new Date() >= end : false;
}

function jobCheckInWindowOpen(job) {
  if (!job?.work_date || !job?.start_time) return false;

  const start = new Date(
    `${job.work_date}T${job.start_time.slice(0, 5)}:00`
  );
  if (Number.isNaN(start.getTime())) return false;

  const opens = new Date(start.getTime() - 2 * 60 * 60 * 1000);
  let end = job.end_time
    ? new Date(`${job.work_date}T${job.end_time.slice(0, 5)}:00`)
    : new Date(start.getTime() + 12 * 60 * 60 * 1000);

  if (job.end_time && end <= start) {
    end = new Date(end.getTime() + 24 * 60 * 60 * 1000);
  }

  const now = new Date();
  return now >= opens && now <= end;
}

function attendanceOutcomeLabel(attendance) {
  const outcome = attendance?.final_outcome || attendance?.employer_outcome;
  if (outcome === "full_day") return "Išdirbo visą dieną";
  if (outcome === "left_early_agreed") return "Išėjo anksčiau – suderinta";
  if (outcome === "left_early_unexcused") return "Išėjo anksčiau be pateisinamos priežasties";
  if (outcome === "no_show") return "Neatvyko";
  return "Darbo diena neuždaryta";
}


function timeRangesOverlap(a, b) {
  if (!a || !b || a.work_date !== b.work_date) return false;
  const aStart = (a.start_time || "00:00").slice(0, 5);
  const aEnd = (a.end_time || "23:59").slice(0, 5);
  const bStart = (b.start_time || "00:00").slice(0, 5);
  const bEnd = (b.end_time || "23:59").slice(0, 5);
  return aStart < bEnd && aEnd > bStart;
}

function normalizeCityKey(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function distanceKmBetweenPoints(a, b) {
  if (!a || !b) return null;

  const lat1 = Number(a.latitude);
  const lon1 = Number(a.longitude);
  const lat2 = Number(b.latitude);
  const lon2 = Number(b.longitude);

  if (![lat1, lon1, lat2, lon2].every(Number.isFinite)) return null;

  const toRad = (degrees) => (degrees * Math.PI) / 180;
  const earthRadiusKm = 6371;

  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);

  const x =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) *
      Math.cos(toRad(lat2)) *
      Math.sin(dLon / 2) ** 2;

  return earthRadiusKm * 2 * Math.atan2(Math.sqrt(x), Math.sqrt(1 - x));
}

function notificationPresentation(events = []) {
  const types = events.map((event) => event.event_type);

  if (types.includes("invitation_declined")) {
    return { tone: "red", label: "⚑ Darbuotojas atsisakė" };
  }
  if (types.includes("invitation_cancelled")) {
    return { tone: "red", label: "⚑ Darbdavys atšaukė" };
  }
  if (types.includes("job_updated")) {
    return { tone: "orange", label: "● Darbas atnaujintas" };
  }
  if (types.includes("invitation_accepted")) {
    return { tone: "green", label: "✓ Darbuotojas priėmė" };
  }
  if (types.includes("attendance_resolved_in_favor")) {
    return { tone: "green", label: "✓ Ginčas išspręstas jūsų naudai" };
  }
  if (types.includes("attendance_resolved_against")) {
    return { tone: "red", label: "Ginčas išspręstas ne jūsų naudai" };
  }
  if (types.includes("attendance_resolved")) {
    return { tone: "green", label: "✓ Ginčas išspręstas" };
  }
  if (types.includes("attendance_disputed")) {
    return { tone: "red", label: "⚑ Darbo dienos ginčas" };
  }
  if (types.includes("attendance_review_required")) {
    return { tone: "orange", label: "● Reikia patvirtinti darbo dieną" };
  }
  if (types.includes("attendance_action_required")) {
    return { tone: "orange", label: "● Reikia uždaryti darbo dieną" };
  }
  if (types.includes("worker_checked_in")) {
    return { tone: "green", label: "✓ Darbuotojas pažymėjo „Atvykau“" };
  }
  if (types.includes("employer_checked_in")) {
    return { tone: "green", label: "✓ Darbdavys patvirtino atvykimą" };
  }
  if (types.includes("attendance_finalized")) {
    return { tone: "green", label: "✓ Darbo diena uždaryta" };
  }
  if (types.includes("invitation_expired")) {
    return { tone: "muted", label: "Kvietimas nebegalioja" };
  }

  return { tone: "orange", label: "● Yra naujienų" };
}

function ConversationModal({
  open,
  onClose,
  onRead,
  invitationId,
  title,
  user,
  senderMode = null,
}) {
  const [messages, setMessages] = useState([]);
  const [names, setNames] = useState({});
  const [textValue, setTextValue] = useState("");
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [conversationLocked, setConversationLocked] = useState(false);
  const [planLocked, setPlanLocked] = useState(false);
  const [cancellationReason, setCancellationReason] = useState("");
  const [error, setError] = useState("");
  const messagesRef = useRef(null);
  const scrollOnLoadRef = useRef(true);
  const loadedConversationRef = useRef(null);

  useEffect(() => {
    if (open && invitationId) {
      scrollOnLoadRef.current = true;
      loadedConversationRef.current = null;
      setMessages([]);
      loadMessages();
    }
  }, [open, invitationId, senderMode]);

  useEffect(() => {
    if (!open || loading || loadedConversationRef.current !== invitationId) return;
    const frame = requestAnimationFrame(() => {
      if (messagesRef.current) {
        messagesRef.current.scrollTop = messagesRef.current.scrollHeight;
      }
      scrollOnLoadRef.current = false;
    });
    if (document.visibilityState === "visible") onRead?.();
    return () => cancelAnimationFrame(frame);
  }, [open, loading, messages, invitationId]);

  async function loadMessages() {
    setLoading(true);
    setError("");
    try {
      const [result, invitationResult] = await Promise.all([
        supabase
          .from("job_messages")
          .select("id, sender_id, sender_context, sender_label, body, created_at")
          .eq("invitation_id", invitationId)
          .order("created_at", { ascending: true }),
        supabase
          .from("job_invitations")
          .select("job_id")
          .eq("id", invitationId)
          .single(),
      ]);

      if (result.error) throw result.error;
      if (invitationResult.error) throw invitationResult.error;

      const [jobResult, chatPlanResult] = await Promise.all([
        supabase
          .from("jobs")
          .select("status, cancellation_reason")
          .eq("id", invitationResult.data.job_id)
          .single(),
        supabase.rpc("job_chat_enabled", {
          p_job_id: invitationResult.data.job_id,
        }),
      ]);

      if (jobResult.error) throw jobResult.error;
      if (chatPlanResult.error) throw chatPlanResult.error;

      const cancelled = jobResult.data?.status === "cancelled";
      const chatPlanLocked = !chatPlanResult.data;

      setPlanLocked(chatPlanLocked);
      setConversationLocked(cancelled || chatPlanLocked);
      setCancellationReason(jobResult.data?.cancellation_reason || "");

      const rows = result.data || [];
      loadedConversationRef.current = invitationId;
      setMessages(rows);

      const ids = [...new Set(rows.map((row) => row.sender_id).filter(Boolean))];
      if (ids.length) {
        const profilesResult = await supabase
          .from("profiles")
          .select("id, display_name")
          .in("id", ids);

        if (profilesResult.error) throw profilesResult.error;

        setNames(
          Object.fromEntries(
            (profilesResult.data || []).map((row) => [
              row.id,
              row.display_name || "Vartotojas",
            ])
          )
        );
      } else {
        setNames({});
      }
    } catch (err) {
      setError(err?.message || "Nepavyko įkelti žinučių.");
    } finally {
      setLoading(false);
    }
  }

  async function sendMessage(e) {
    e.preventDefault();
    const body = textValue.trim();
    if (!body || !invitationId || conversationLocked) return;

    setSending(true);
    setError("");
    try {
      const result = senderMode
        ? await supabase.rpc("admin_send_private_job_message_as_mode", {
            p_invitation_id: invitationId,
            p_body: body,
            p_mode: senderMode,
          })
        : await supabase.from("job_messages").insert({
            invitation_id: invitationId,
            sender_id: user.id,
            body,
          });

      if (result.error) throw result.error;

      setTextValue("");
      scrollOnLoadRef.current = true;
      await loadMessages();
    } catch (err) {
      setError(err?.message || "Nepavyko išsiųsti žinutės.");
    } finally {
      setSending(false);
    }
  }

  if (!open) return null;

  return (
    <div className="rs-modal-overlay" onMouseDown={(e) => {
      if (e.target === e.currentTarget) onClose();
    }}>
      <div className="rs-modal-card">
        <style>{`
          .rs-modal-overlay{position:fixed;inset:0;background:rgba(16,36,56,.62);z-index:2000;display:grid;place-items:center;padding:20px;backdrop-filter:blur(2px)}
          .rs-modal-card{width:min(760px,100%);max-height:calc(100vh - 40px);display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;overflow:hidden;background:#fff;border-radius:22px;box-shadow:0 28px 90px rgba(16,36,56,.28);padding:22px;color:#102438}
          .rs-modal-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:14px}
          .rs-modal-head h2{margin:6px 0 0;font-size:24px;line-height:1.2;font-family:Manrope,Inter,sans-serif}.rs-close{border:0;background:#f2f5f7;border-radius:12px;width:42px;height:42px;font-size:20px;cursor:pointer;display:grid;place-items:center;flex:0 0 42px}
          .rs-messages{display:grid;align-content:start;justify-items:start;gap:10px;overflow:auto;padding:16px;background:#f8fafb;border:1px solid #e8eef2;border-radius:18px;min-height:260px;max-height:420px}
          .rs-message{width:fit-content;max-width:min(84%,560px);border:1px solid #dfe7ec;border-radius:16px 16px 16px 6px;padding:12px 14px;background:#fff;box-shadow:0 2px 8px rgba(16,36,56,.04)}
          .rs-message.mine{justify-self:end;background:#fff6ee;border-color:#f3d4b7;border-radius:16px 16px 6px 16px}
          .rs-message.admin{background:#f3f8fb;border-color:#cfe0ec}.rs-message b{display:block;font-size:12px;margin-bottom:5px}.rs-message p{margin:0;white-space:pre-wrap;line-height:1.5;overflow-wrap:anywhere}
          .rs-message time{display:block;margin-top:7px;font-size:10px;color:#7a8996}
          .rs-msg-form{display:grid;grid-template-columns:minmax(0,1fr) 116px;align-items:end;gap:12px;border-top:1px solid #e5ebef;padding-top:14px;margin-top:14px}
          .rs-msg-form textarea{width:100%;min-height:74px;max-height:140px;resize:vertical;border:1px solid #d7e0e7;border-radius:16px;padding:14px 15px;font:inherit;color:#102438;outline:none;line-height:1.45;background:#fff}
          .rs-msg-form textarea:focus{border-color:#f08a28;box-shadow:0 0 0 3px rgba(240,138,40,.12)}
          .rs-msg-form button{height:54px;align-self:end;min-width:0;border:0;background:#f08a28;color:#fff;border-radius:16px;padding:0 17px;font:inherit;font-weight:800;cursor:pointer}
          .rs-msg-form button:disabled{opacity:.55;cursor:not-allowed}.rs-error{background:#fff0ec;color:#b64d2a;border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:12px}
          .rs-empty{color:#6c7a88;text-align:center;padding:28px 10px;justify-self:stretch}.rs-locked{background:#fff0ec;color:#9f4529;border-radius:10px;padding:11px 12px;margin:4px 0 12px;font-size:13px;line-height:1.45}
          .rs-group-note{background:#edf8f3;color:#167a54;border-radius:12px;padding:10px 12px;margin-bottom:12px;font-size:13px;line-height:1.45}
          .dispute-parties{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;color:#6c7a88;font-size:12px}.dispute-party{background:#f2f5f7;border-radius:999px;padding:5px 9px}
          @media(max-width:620px){.rs-modal-overlay{padding:10px}.rs-modal-card{width:calc(100vw - 20px);max-height:calc(100vh - 20px);border-radius:16px;padding:17px}.rs-msg-form{grid-template-columns:1fr}.rs-msg-form button{width:100%;height:46px}.rs-message{max-width:92%}}
        `}</style>

        <div className="rs-modal-head">
          <div>
            <div className="eyebrow">ŽINUTĖS</div>
            <h2>{title || "Pokalbis apie darbą"}</h2>
          </div>
          <button className="rs-close" onClick={onClose}><CloseMark /></button>
        </div>

        {error && <div className="rs-error">{error}</div>}

        <ChatConductNotice />

        <div className="rs-messages" ref={messagesRef}>
          {loading ? (
            <div className="lt-chat-empty">Kraunama...</div>
          ) : messages.length ? (
            messages.map((message) => (
              <div
                className={message.sender_id === user.id ? "rs-message mine" : "rs-message"}
                key={message.id}
              >
                <b>
                  {message.sender_label ||
                    names[message.sender_id] ||
                    (message.sender_id === user.id ? "Jūs" : "Vartotojas")}
                </b>
                <p>{message.body}</p>
                <time>
                  {new Date(message.created_at).toLocaleString("lt-LT", {
                    dateStyle: "short",
                    timeStyle: "short",
                  })}
                </time>
              </div>
            ))
          ) : (
            <div className="rs-empty">Žinučių dar nėra. Galite parašyti pirmą.</div>
          )}
        </div>

        {conversationLocked && (
          <div className="rs-locked">
            {planLocked ? (
              <>
                <b>Darbo pokalbiai šiame darbe neaktyvūs.</b>
                <div style={{ marginTop: 4 }}>
                  Darbdavys naudoja Basic planą. Žinučių funkcija įtraukta į
                  Business ir Business Pro planus.
                </div>
              </>
            ) : (
              <>
                <b>Šis darbas atšauktas — pokalbis uždarytas.</b>
                {cancellationReason && (
                  <div style={{ marginTop: 4 }}>
                    Atšaukimo priežastis: {cancellationReason}
                  </div>
                )}
                <div style={{ marginTop: 4 }}>
                  Ankstesnes žinutes galite perskaityti, tačiau naujų siųsti
                  nebegalima.
                </div>
              </>
            )}
          </div>
        )}

        <form className="rs-msg-form" onSubmit={sendMessage}>
          <textarea
            value={textValue}
            onChange={(e) => setTextValue(e.target.value)}
            onKeyDown={(e) => {
              if (
                e.key === "Enter" &&
                !e.shiftKey &&
                !e.nativeEvent?.isComposing
              ) {
                e.preventDefault();
                if (
                  !conversationLocked &&
                  !sending &&
                  textValue.trim()
                ) {
                  sendMessage(e);
                }
              }
            }}
            maxLength={2000}
            disabled={conversationLocked}
            placeholder={
              conversationLocked
                ? "Pokalbis uždarytas"
                : "Parašykite žinutę..."
            }
          />
          <button disabled={conversationLocked || sending || !textValue.trim()}>
            {sending ? "Siunčiama..." : "Siųsti"}
          </button>
        </form>
      </div>
    </div>
  );
}


function DisputeConversationModal({
  open,
  onClose,
  attendanceId,
  title,
  workerName,
  companyName,
  user,
}) {
  const [messages, setMessages] = useState([]);
  const [textValue, setTextValue] = useState("");
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const messagesRef = useRef(null);
  const scrollOnLoadRef = useRef(true);

  useEffect(() => {
    if (!open || !attendanceId) return;

    scrollOnLoadRef.current = true;
    setMessages([]);
    loadMessages();

    const timer = window.setInterval(loadMessages, 3000);
    return () => window.clearInterval(timer);
  }, [open, attendanceId]);

  useEffect(() => {
    if (!open || loading || !messagesRef.current) return;

    const frame = requestAnimationFrame(() => {
      if (messagesRef.current) {
        messagesRef.current.scrollTop = messagesRef.current.scrollHeight;
      }
      scrollOnLoadRef.current = false;
    });

    return () => cancelAnimationFrame(frame);
  }, [open, loading, messages]);

  async function loadMessages() {
    if (!attendanceId) return;

    setLoading(true);
    setError("");
    try {
      const result = await supabase.rpc(
        "get_attendance_dispute_chat_messages",
        { p_attendance_id: attendanceId }
      );

      if (result.error) throw result.error;
      setMessages(result.data || []);
    } catch (err) {
      setError(err?.message || "Nepavyko įkelti ginčo žinučių.");
    } finally {
      setLoading(false);
    }
  }

  async function sendMessage(e) {
    e.preventDefault();
    const body = textValue.trim();
    if (!body || !attendanceId || sending) return;

    setSending(true);
    setError("");
    try {
      const result = await supabase.rpc(
        "send_attendance_dispute_chat_message",
        {
          p_attendance_id: attendanceId,
          p_body: body,
        }
      );

      if (result.error) throw result.error;

      setTextValue("");
      scrollOnLoadRef.current = true;
      await loadMessages();
    } catch (err) {
      setError(err?.message || "Nepavyko išsiųsti žinutės.");
    } finally {
      setSending(false);
    }
  }

  function senderLabel(message) {
    if (message.sender_name) return message.sender_name;
    if (message.sender_role === "admin") return "Administratorius";
    if (message.sender_role === "worker") {
      return workerName ? `Darbuotojas ${workerName}` : "Darbuotojas";
    }
    if (message.sender_role === "employer") {
      return companyName ? `${companyName} · Darbdavys` : "Darbdavys";
    }
    return "Vartotojas";
  }

  if (!open) return null;

  return (
    <div
      className="rs-modal-overlay"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="rs-modal-card">
        <style>{`
          .rs-modal-overlay{position:fixed;inset:0;background:rgba(16,36,56,.62);z-index:2000;display:grid;place-items:center;padding:20px;backdrop-filter:blur(2px)}
          .rs-modal-card{width:min(720px,100%);max-height:calc(100vh - 40px);display:grid;grid-template-rows:auto auto minmax(180px,1fr) auto;overflow:hidden;background:#fff;border-radius:20px;box-shadow:0 28px 90px rgba(16,36,56,.28);padding:22px;color:#102438}
          .rs-modal-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:14px}
          .rs-modal-head h2{margin:6px 0 0;font-size:24px;line-height:1.2;font-family:Manrope,Inter,sans-serif}.rs-close{border:0;background:#f2f5f7;border-radius:12px;width:42px;height:42px;font-size:20px;cursor:pointer;display:grid;place-items:center;flex:0 0 42px}
          .dispute-parties{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;color:#6c7a88;font-size:12px}.dispute-party{background:#f2f5f7;border-radius:999px;padding:5px 9px}
          .rs-messages{display:grid;align-content:start;gap:10px;overflow:auto;padding:18px 4px 14px;background:#f8fafb;border:1px solid #e8eef2;border-radius:16px;min-height:220px;max-height:420px}
          .rs-message{max-width:min(84%,560px);border:1px solid #dfe7ec;border-radius:14px 14px 14px 5px;padding:11px 13px;background:#fff;box-shadow:0 2px 8px rgba(16,36,56,.04)}
          .rs-message.mine{margin-left:auto;background:#fff6ee;border-color:#f3d4b7;border-radius:14px 14px 5px 14px}.rs-message.admin{background:#f3f8fb;border-color:#cfe0ec}
          .rs-message b{display:block;font-size:12px;margin-bottom:5px}.rs-message p{margin:0;white-space:pre-wrap;line-height:1.45;overflow-wrap:anywhere}.rs-message time{display:block;margin-top:7px;font-size:10px;color:#7a8996}
          .rs-msg-form{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;border-top:1px solid #e5ebef;padding-top:14px;margin-top:14px}
          .rs-msg-form textarea{width:100%;min-height:54px;max-height:130px;resize:vertical;border:1px solid #d7e0e7;border-radius:12px;padding:11px 12px;font:inherit;color:#102438;outline:none}
          .rs-msg-form textarea:focus{border-color:#f08a28;box-shadow:0 0 0 3px rgba(240,138,40,.12)}
          .rs-msg-form button{align-self:stretch;min-width:92px;border:0;background:#f08a28;color:#fff;border-radius:11px;padding:0 17px;font:inherit;font-weight:800;cursor:pointer}
          .rs-msg-form button:disabled{opacity:.55;cursor:not-allowed}.rs-error{background:#fff0ec;color:#b64d2a;border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:12px}
          .rs-empty{color:#6c7a88;text-align:center;padding:28px 10px}
          @media(max-width:620px){.rs-modal-overlay{padding:10px}.rs-modal-card{width:calc(100vw - 20px);max-height:calc(100vh - 20px);border-radius:16px;padding:17px}.rs-msg-form{grid-template-columns:1fr}.rs-msg-form button{min-height:44px}.rs-message{max-width:92%}}
        `}</style>

        <div className="rs-modal-head">
          <div>
            <div className="eyebrow">GINČO POKALBIS</div>
            <h2>{title || "Ginčo aptarimas"}</h2>
            <div className="dispute-parties">
              {workerName && <span className="dispute-party">Darbuotojas: {workerName}</span>}
              {companyName && <span className="dispute-party">Darbdavys: {companyName}</span>}
              <span className="dispute-party">Administratorius</span>
            </div>
          </div>
          <button className="rs-close" onClick={onClose}>
            <CloseMark />
          </button>
        </div>

        {error && <div className="rs-error">{error}</div>}

        <ChatConductNotice />

        <div className="rs-messages" ref={messagesRef}>
          {loading && !messages.length ? (
            <div className="rs-empty">Kraunama...</div>
          ) : messages.length ? (
            messages.map((message) => {
              const mine = message.sender_id === user?.id;
              const className = [
                "rs-message",
                mine ? "mine" : "",
                message.sender_role === "admin" ? "admin" : "",
              ]
                .filter(Boolean)
                .join(" ");

              return (
                <div className={className} key={message.message_id}>
                  <b>{senderLabel(message)}</b>
                  <p>{message.body}</p>
                  <time>
                    {new Date(message.created_at).toLocaleString("lt-LT", {
                      dateStyle: "short",
                      timeStyle: "short",
                    })}
                  </time>
                </div>
              );
            })
          ) : (
            <div className="lt-chat-empty">Žinučių dar nėra. Galite pradėti aptarimą.</div>
          )}
        </div>

        <form className="rs-msg-form" onSubmit={sendMessage}>
          <textarea
            value={textValue}
            onChange={(e) => setTextValue(e.target.value)}
            onKeyDown={(e) => {
              if (
                e.key === "Enter" &&
                !e.shiftKey &&
                !e.nativeEvent?.isComposing
              ) {
                e.preventDefault();
                if (!sending && textValue.trim()) sendMessage(e);
              }
            }}
            maxLength={2000}
            placeholder="Parašykite žinutę abiem ginčo pusėms..."
          />
          <button disabled={sending || !textValue.trim()}>
            {sending ? "Siunčiama..." : "Siųsti"}
          </button>
        </form>
      </div>
    </div>
  );
}


function GroupConversationModal({
  open,
  onClose,
  onRead,
  jobId,
  title,
  user,
  senderMode = null,
}) {
  const [messages, setMessages] = useState([]);
  const [names, setNames] = useState({});
  const [textValue, setTextValue] = useState("");
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [conversationLocked, setConversationLocked] = useState(false);
  const [planLocked, setPlanLocked] = useState(false);
  const [cancellationReason, setCancellationReason] = useState("");
  const [error, setError] = useState("");
  const messagesRef = useRef(null);
  const scrollOnLoadRef = useRef(true);
  const loadedConversationRef = useRef(null);

  useEffect(() => {
    if (!open || !jobId) return;

    scrollOnLoadRef.current = true;
    loadedConversationRef.current = null;
    setMessages([]);
    loadMessages();
    const timer = setInterval(loadMessages, 3000);
    return () => clearInterval(timer);
  }, [open, jobId, senderMode]);

  useEffect(() => {
    if (!open || loading || loadedConversationRef.current !== jobId) return;
    const frame = requestAnimationFrame(() => {
      if (messagesRef.current) {
        messagesRef.current.scrollTop = messagesRef.current.scrollHeight;
      }
      scrollOnLoadRef.current = false;
    });
    if (document.visibilityState === "visible") onRead?.();
    return () => cancelAnimationFrame(frame);
  }, [open, loading, messages, jobId]);

  async function loadMessages() {
    if (!messages.length) setLoading(true);
    setError("");

    try {
      const [messagesResult, jobResult, chatPlanResult] = await Promise.all([
        supabase
          .from("job_group_messages")
          .select("id, sender_id, sender_context, sender_label, body, created_at")
          .eq("job_id", jobId)
          .order("created_at", { ascending: true }),
        supabase
          .from("jobs")
          .select("status, cancellation_reason")
          .eq("id", jobId)
          .single(),
        supabase.rpc("job_chat_enabled", {
          p_job_id: jobId,
        }),
      ]);

      if (messagesResult.error) throw messagesResult.error;
      if (jobResult.error) throw jobResult.error;
      if (chatPlanResult.error) throw chatPlanResult.error;

      const chatPlanLocked = !chatPlanResult.data;
      setPlanLocked(chatPlanLocked);
      setConversationLocked(
        jobResult.data?.status === "cancelled" || chatPlanLocked
      );
      setCancellationReason(jobResult.data?.cancellation_reason || "");

      const rows = messagesResult.data || [];
      loadedConversationRef.current = jobId;
      setMessages(rows);

      const ids = [...new Set(rows.map((row) => row.sender_id).filter(Boolean))];
      if (ids.length) {
        const profilesResult = await supabase
          .from("profiles")
          .select("id, display_name")
          .in("id", ids);

        if (profilesResult.error) throw profilesResult.error;

        setNames(
          Object.fromEntries(
            (profilesResult.data || []).map((row) => [
              row.id,
              row.display_name || "Vartotojas",
            ])
          )
        );
      } else {
        setNames({});
      }
    } catch (err) {
      setError(err?.message || "Nepavyko įkelti darbo pokalbio.");
    } finally {
      setLoading(false);
    }
  }

  async function sendMessage(e) {
    e.preventDefault();
    const body = textValue.trim();
    if (!body || !jobId || conversationLocked) return;

    setSending(true);
    setError("");

    try {
      const result = senderMode
        ? await supabase.rpc("admin_send_job_chat_as_mode", {
            p_job_id: jobId,
            p_body: body,
            p_mode: senderMode,
          })
        : await supabase.from("job_group_messages").insert({
            job_id: jobId,
            sender_id: user.id,
            body,
          });

      if (result.error) throw result.error;

      setTextValue("");
      scrollOnLoadRef.current = true;
      await loadMessages();
    } catch (err) {
      setError(err?.message || "Nepavyko išsiųsti žinutės.");
    } finally {
      setSending(false);
    }
  }

  if (!open) return null;

  return (
    <div
      className="rs-modal-overlay"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="rs-modal-card">
        <style>{`
          .rs-modal-overlay{position:fixed;inset:0;background:rgba(16,36,56,.62);z-index:2000;display:grid;place-items:center;padding:20px;backdrop-filter:blur(2px)}
          .rs-modal-card{width:min(760px,100%);max-height:calc(100vh - 40px);display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;overflow:hidden;background:#fff;border-radius:22px;box-shadow:0 28px 90px rgba(16,36,56,.28);padding:22px;color:#102438}
          .rs-modal-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:14px}
          .rs-modal-head h2{margin:6px 0 0;font-size:24px;line-height:1.2;font-family:Manrope,Inter,sans-serif}.rs-close{border:0;background:#f2f5f7;border-radius:12px;width:42px;height:42px;font-size:20px;cursor:pointer;display:grid;place-items:center;flex:0 0 42px}
          .rs-messages{display:grid;align-content:start;justify-items:start;gap:10px;overflow:auto;padding:16px;background:#f8fafb;border:1px solid #e8eef2;border-radius:18px;min-height:260px;max-height:420px}
          .rs-message{width:fit-content;max-width:min(84%,560px);border:1px solid #dfe7ec;border-radius:16px 16px 16px 6px;padding:12px 14px;background:#fff;box-shadow:0 2px 8px rgba(16,36,56,.04)}
          .rs-message.mine{justify-self:end;background:#fff6ee;border-color:#f3d4b7;border-radius:16px 16px 6px 16px}
          .rs-message.admin{background:#f3f8fb;border-color:#cfe0ec}.rs-message b{display:block;font-size:12px;margin-bottom:5px}.rs-message p{margin:0;white-space:pre-wrap;line-height:1.5;overflow-wrap:anywhere}
          .rs-message time{display:block;margin-top:7px;font-size:10px;color:#7a8996}
          .rs-msg-form{display:grid;grid-template-columns:minmax(0,1fr) 116px;align-items:end;gap:12px;border-top:1px solid #e5ebef;padding-top:14px;margin-top:14px}
          .rs-msg-form textarea{width:100%;min-height:74px;max-height:140px;resize:vertical;border:1px solid #d7e0e7;border-radius:16px;padding:14px 15px;font:inherit;color:#102438;outline:none;line-height:1.45;background:#fff}
          .rs-msg-form textarea:focus{border-color:#f08a28;box-shadow:0 0 0 3px rgba(240,138,40,.12)}
          .rs-msg-form button{height:54px;align-self:end;min-width:0;border:0;background:#f08a28;color:#fff;border-radius:16px;padding:0 17px;font:inherit;font-weight:800;cursor:pointer}
          .rs-msg-form button:disabled{opacity:.55;cursor:not-allowed}.rs-error{background:#fff0ec;color:#b64d2a;border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:12px}
          .rs-empty{color:#6c7a88;text-align:center;padding:28px 10px;justify-self:stretch}.rs-locked{background:#fff0ec;color:#9f4529;border-radius:10px;padding:11px 12px;margin:4px 0 12px;font-size:13px;line-height:1.45}
          .rs-group-note{background:#edf8f3;color:#167a54;border-radius:12px;padding:10px 12px;margin-bottom:12px;font-size:13px;line-height:1.45}
          .dispute-parties{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;color:#6c7a88;font-size:12px}.dispute-party{background:#f2f5f7;border-radius:999px;padding:5px 9px}
          @media(max-width:620px){.rs-modal-overlay{padding:10px}.rs-modal-card{width:calc(100vw - 20px);max-height:calc(100vh - 20px);border-radius:16px;padding:17px}.rs-msg-form{grid-template-columns:1fr}.rs-msg-form button{width:100%;height:46px}.rs-message{max-width:92%}}
        `}</style>

        <div className="rs-modal-head">
          <div>
            <div className="eyebrow">DARBO POKALBIS</div>
            <h2>{title || "Bendras darbo pokalbis"}</h2>
          </div>
          <button className="rs-close" onClick={onClose}><CloseMark /></button>
        </div>

        <div className="rs-group-note">
          {senderMode === "worker"
            ? "Rašote darbuotojo režimu. Žinutė bus rodoma jūsų darbuotojo vardu."
            : senderMode === "employer"
            ? "Rašote darbdavio režimu. Žinutė bus rodoma jūsų įmonės vardu."
            : "Šį pokalbį mato darbdavys ir visi šį darbą patvirtinę darbuotojai."}
        </div>

        {error && <div className="rs-error">{error}</div>}

        <ChatConductNotice />

        <div className="rs-messages" ref={messagesRef}>
          {loading && !messages.length ? (
            <div className="rs-empty">Kraunama...</div>
          ) : messages.length ? (
            messages.map((message) => (
              <div
                className={
                  message.sender_id === user.id
                    ? "rs-message mine"
                    : "rs-message"
                }
                key={message.id}
              >
                <b>
                  {message.sender_label ||
                    names[message.sender_id] ||
                    (message.sender_id === user.id ? "Jūs" : "Vartotojas")}
                </b>
                <p>{message.body}</p>
                <time>
                  {new Date(message.created_at).toLocaleString("lt-LT", {
                    dateStyle: "short",
                    timeStyle: "short",
                  })}
                </time>
              </div>
            ))
          ) : (
            <div className="rs-empty">
              Darbo pokalbis dar tuščias. Galite parašyti pirmą žinutę.
            </div>
          )}
        </div>

        {conversationLocked && (
          <div className="rs-locked">
            {planLocked ? (
              <>
                <b>Darbo pokalbiai šiame darbe neaktyvūs.</b>
                <div style={{ marginTop: 4 }}>
                  Darbdavys naudoja Basic planą. Bendri ir privatūs darbo
                  pokalbiai įtraukti į Business ir Business Pro.
                </div>
              </>
            ) : (
              <>
                <b>Šis darbas atšauktas — darbo pokalbis uždarytas.</b>
                {cancellationReason && (
                  <div style={{ marginTop: 4 }}>
                    Atšaukimo priežastis: {cancellationReason}
                  </div>
                )}
              </>
            )}
          </div>
        )}

        <form className="rs-msg-form" onSubmit={sendMessage}>
          <textarea
            value={textValue}
            onChange={(e) => setTextValue(e.target.value)}
            onKeyDown={(e) => {
              if (
                e.key === "Enter" &&
                !e.shiftKey &&
                !e.nativeEvent?.isComposing
              ) {
                e.preventDefault();
                if (
                  !conversationLocked &&
                  !sending &&
                  textValue.trim()
                ) {
                  sendMessage(e);
                }
              }
            }}
            maxLength={2000}
            disabled={conversationLocked}
            placeholder={
              conversationLocked
                ? "Pokalbis uždarytas"
                : "Žinutė visai darbo komandai..."
            }
          />
          <button disabled={conversationLocked || sending || !textValue.trim()}>
            {sending ? "Siunčiama..." : "Siųsti"}
          </button>
        </form>
      </div>
    </div>
  );
}



function longTermWeekdayLabel(day) {
  return ({
    1: "Pirmadienis",
    2: "Antradienis",
    3: "Trečiadienis",
    4: "Ketvirtadienis",
    5: "Penktadienis",
    6: "Šeštadienis",
    7: "Sekmadienis",
  })[Number(day)] || "Diena";
}

function longTermContractLabel(value) {
  return value === "fixed_term" ? "Terminuota" : "Neterminuota";
}

function longTermSalaryBasisLabel(value) {
  return value === "gross" ? "ant popieriaus" : "į rankas";
}

function safeStorageFileName(name) {
  return String(name || "failas")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9._-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "") || "failas";
}

async function openEmploymentContract(storagePath) {
  if (!storagePath) return false;
  const result = await supabase.storage
    .from("employment-contracts")
    .createSignedUrl(storagePath, 60 * 10);
  if (result.error || !result.data?.signedUrl) {
    throw result.error || new Error("Nepavyko atidaryti sutarties.");
  }
  window.open(result.data.signedUrl, "_blank", "noopener,noreferrer");
  return true;
}

function defaultLongTermSchedule() {
  return [1, 2, 3, 4, 5, 6, 7].map((weekday) => ({
    weekday,
    enabled: weekday <= 5,
    startTime: "08:00",
    endTime: "17:00",
    noBreak: false,
    breakStartTime: "12:00",
    breakEndTime: "12:30",
  }));
}

function longTermStatusLabel(value) {
  return ({
    offered: "Pasiūlymas pateiktas",
    active: "Aktyvus įdarbinimas",
    declined: "Pasiūlymas atmestas",
    withdrawn: "Pasiūlymas atšauktas",
    ended: "Įdarbinimas pasibaigęs",
  })[value] || value || "Pasiūlymas";
}

function longTermEmployerUpdateLabel(offer) {
  if (!offer) return "Pasiūlymas pateiktas";
  if (offer.status === "active") return "Darbuotojas priimtas";
  if (offer.worker_signed_contract_path) {
    return "Pasirašyta sutartis gauta · patvirtinkite įdarbinimą arba atšaukite pasiūlymą";
  }
  if (offer.worker_contract_viewed_at) return "Darbuotojas peržiūrėjo sutartį";
  if (offer.worker_viewed_at) return "Darbuotojas peržiūrėjo pasiūlymą";
  return "Pasiūlymas pateiktas";
}

function longTermEmployerUpdateTone(offer) {
  if (!offer) return "muted";
  if (offer.status === "active" || offer.worker_signed_contract_path) return "success";
  if (offer.worker_contract_viewed_at) return "attention";
  return "muted";
}

function longTermWorkerUpdateLabel(offer) {
  if (!offer) return "Darbdavys atsiuntė pasiūlymą";
  if (offer.status === "active") return "Darbdavys patvirtino įdarbinimą";
  if (offer.worker_signed_contract_path) {
    return "Pasirašyta sutartis įkelta · laukiamas sprendimas";
  }
  if (offer.worker_contract_viewed_at) return "Sutartis peržiūrėta";
  if (offer.worker_viewed_at) return "Pasiūlymas peržiūrėtas";
  return "Darbdavys atsiuntė pasiūlymą";
}

function longTermWorkerUpdateTone(offer) {
  if (!offer) return "orange";
  if (offer.status === "active" || offer.worker_signed_contract_path) return "green";
  if (offer.worker_contract_viewed_at) return "green";
  if (offer.worker_viewed_at) return "muted";
  return "orange";
}

function LongTermOfferDetails({ offer }) {
  if (!offer) return null;

  const schedule = Array.isArray(offer.schedule) ? offer.schedule : [];

  return (
    <div style={{ display: "grid", gap: 12 }}>
      <div className="lt-detail-grid">
        <div className="lt-detail-card">
          <span>Darbo pozicija</span>
          <b>{offer.position_title || "—"}</b>
        </div>
        <div className="lt-detail-card">
          <span>Sutartis</span>
          <b>{longTermContractLabel(offer.contract_type)}</b>
        </div>
        <div className="lt-detail-card">
          <span>Preliminari pradžia</span>
          <b>{offer.proposed_start_date || "—"}</b>
        </div>
        <div className="lt-detail-card">
          <span>Pabaiga</span>
          <b>
            {offer.contract_type === "fixed_term"
              ? offer.proposed_end_date || "—"
              : "Neterminuota"}
          </b>
        </div>
        <div className="lt-detail-card">
          <span>Darbo vieta</span>
          <b>{offer.workplace_city || "—"}</b>
          {offer.workplace_address && (
            <small>Atvykti adresu: {offer.workplace_address}</small>
          )}
        </div>
        <div className="lt-detail-card">
          <span>Siūlomas atlygis</span>
          <b>
            {offer.salary_amount
              ? `${offer.salary_amount} € ${longTermSalaryBasisLabel(
                  offer.salary_basis
                )} ${
                  offer.salary_period === "monthly" ? "/ mėn." : "/ val."
                }`
              : "Nenurodytas"}
          </b>
          {offer.salary_note && <small>{offer.salary_note}</small>}
        </div>
      </div>

      <div className="lt-detail-card">
        <span>Įdarbinimo informacija</span>
        <div style={{ marginTop: 5, lineHeight: 1.55, whiteSpace: "pre-wrap" }}>
          {offer.employment_details?.trim() ||
            "Darbdavys papildomos informacijos nepateikė."}
        </div>
      </div>

      <div className="lt-detail-card">
        <span>Siūlomas darbo grafikas</span>
        {offer.schedule_type === "variable" ? (
          <div style={{ marginTop: 6, lineHeight: 1.5 }}>
            Kintamas grafikas. Konkretų prieinamumą darbuotojas ir toliau valdo
            savo workforce grafike.
          </div>
        ) : schedule.length ? (
          <div className="lt-schedule-table">
            {schedule.map((row) => (
              <div className="lt-schedule-row" key={`${offer.id}-${row.weekday}`}>
                <b>{longTermWeekdayLabel(row.weekday)}</b>
                <span>
                  {String(row.start_time || "").slice(0, 5)}–
                  {String(row.end_time || "").slice(0, 5)}
                </span>
                <span>
                  {row.break_start_time && row.break_end_time
                    ? `Pietūs ${String(row.break_start_time).slice(0, 5)}–${String(
                        row.break_end_time
                      ).slice(0, 5)}`
                    : "Pietų pertraukos nėra"}
                </span>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ marginTop: 6 }}>Grafikas nenurodytas.</div>
        )}
      </div>
    </div>
  );
}

function LongTermConversationModal({ open, onClose, placementId, title, user }) {
  const [messages, setMessages] = useState([]);
  const [textValue, setTextValue] = useState("");
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const messagesRef = useRef(null);
  const scrollOnLoadRef = useRef(true);

  useEffect(() => {
    if (!open || !placementId) return;
    scrollOnLoadRef.current = true;
    setMessages([]);
    loadMessages();
    const timer = window.setInterval(loadMessages, 3000);
    return () => window.clearInterval(timer);
  }, [open, placementId]);

  useEffect(() => {
    if (!open || loading || !messagesRef.current) return;
    const frame = requestAnimationFrame(() => {
      if (messagesRef.current) {
        messagesRef.current.scrollTop = messagesRef.current.scrollHeight;
      }
      scrollOnLoadRef.current = false;
    });
    return () => cancelAnimationFrame(frame);
  }, [open, loading, messages]);

  async function loadMessages() {
    if (!placementId) return;
    setLoading(true);
    setError("");
    try {
      const result = await supabase.rpc("get_long_term_messages", {
        p_placement_id: placementId,
      });
      if (result.error) throw result.error;
      setMessages(result.data || []);
      const readResult = await supabase.rpc("mark_long_term_messages_read", {
        p_placement_id: placementId,
      });
      if (readResult.error) throw readResult.error;
    } catch (err) {
      setError(err?.message || "Nepavyko įkelti pokalbio.");
    } finally {
      setLoading(false);
    }
  }

  async function sendMessage(e) {
    e.preventDefault();
    const body = textValue.trim();
    if (!body || sending || !placementId) return;
    setSending(true);
    setError("");
    try {
      const result = await supabase.rpc("send_long_term_message", {
        p_placement_id: placementId,
        p_body: body,
      });
      if (result.error) throw result.error;
      setTextValue("");
      scrollOnLoadRef.current = true;
      await loadMessages();
    } catch (err) {
      setError(err?.message || "Nepavyko išsiųsti žinutės.");
    } finally {
      setSending(false);
    }
  }

  if (!open) return null;

  return (
    <div
      className="rs-modal-overlay lt-chat-overlay"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <style>{`
        .lt-chat-overlay{position:fixed;inset:0;z-index:2800;display:grid;place-items:center;padding:20px;background:rgba(16,36,56,.62);backdrop-filter:blur(2px)}
        .lt-chat-card{width:min(720px,calc(100vw - 40px));max-height:calc(100vh - 40px);display:grid;grid-template-rows:auto minmax(180px,1fr) auto;overflow:hidden;background:#fff;border-radius:20px;box-shadow:0 28px 90px rgba(16,36,56,.3);color:#102438}
        .lt-chat-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:22px 22px 18px;border-bottom:1px solid #e8eef2}
        .lt-chat-head h2{margin:5px 0 0;font-size:24px;line-height:1.2}.lt-chat-head p{margin:6px 0 0;color:#6c7a88;font-size:13px;line-height:1.45}
        .lt-chat-close{border:0;background:#f2f5f7;color:#102438;border-radius:12px;width:42px;height:42px;display:grid;place-items:center;cursor:pointer;flex:0 0 42px}
        .lt-chat-body{overflow:auto;padding:18px 20px 20px;display:grid;gap:10px;align-content:start;background:#f5f8fa}
        .lt-chat-body .chat-conduct-inline{margin:0 0 4px}
        .lt-chat-empty{padding:18px;border:1px dashed #d7e0e7;border-radius:13px;background:#fff;color:#71808d;text-align:center;font-size:13px}
        .lt-chat-message{width:min(82%,560px);padding:10px 12px 11px;border:1px solid #dce5eb;border-radius:16px 16px 16px 6px;background:#fff;box-shadow:0 3px 10px rgba(16,36,56,.04)}
        .lt-chat-message.mine{justify-self:end;border-color:#f0cda9;background:#fff7ef;border-radius:16px 16px 6px 16px}.lt-chat-message-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:6px}.lt-chat-message-sender{display:flex;align-items:center;gap:7px;min-width:0}.lt-chat-message-sender b{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.lt-chat-role{display:inline-flex;align-items:center;border-radius:999px;padding:3px 7px;background:#edf2f5;color:#607180;font-size:9px;font-weight:850;line-height:1}.lt-chat-message.mine .lt-chat-role{background:#ffe8d3;color:#a85a17}.lt-chat-message p{margin:0;color:#263b4d;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere}.lt-chat-message time{flex:0 0 auto;color:#8a98a6;font-size:10px;white-space:nowrap}
        .lt-chat-error{margin:0 0 4px;background:#fff0ec;color:#b64d2a;border:1px solid #f0c7bc;border-radius:11px;padding:10px 12px;font-size:12px}
        .lt-chat-form{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:14px 16px 16px;border-top:1px solid #e8eef2;background:#fff}
        .lt-chat-form textarea{width:100%;min-height:54px;max-height:130px;resize:vertical;border:1px solid #d7e0e7;border-radius:12px;padding:11px 12px;font:inherit;color:#102438;outline:none}.lt-chat-form textarea:focus{border-color:#f08a28;box-shadow:0 0 0 3px rgba(240,138,40,.12)}
        .lt-chat-form button{align-self:stretch;min-width:92px;border:0;background:#f08a28;color:#fff;border-radius:11px;padding:0 17px;font:inherit;font-weight:800;cursor:pointer}.lt-chat-form button:disabled{opacity:.45;cursor:not-allowed}
        @media(max-width:620px){.lt-chat-overlay{padding:10px}.lt-chat-card{width:calc(100vw - 20px);max-height:calc(100vh - 20px);border-radius:16px}.lt-chat-head{padding:17px}.lt-chat-form{grid-template-columns:1fr}.lt-chat-form button{min-height:44px}.lt-chat-message{width:92%}}
      `}</style>
      <div className="lt-chat-card">
        <div className="lt-chat-head">
          <div>
            <div className="eyebrow">ILGALAIKIO DARBO POKALBIS</div>
            <h2>{title || "Aptarti pasiūlymą"}</h2>
            <p style={{ margin: "6px 0 0", color: "#6c7a88", fontSize: 13 }}>
              Čia galite aptarti ilgalaikio darbo sąlygas, sutartį ir kitus su įdarbinimu susijusius klausimus.
            </p>
          </div>
          <button className="lt-chat-close" type="button" onClick={onClose} aria-label="Uždaryti pokalbį">
            <CloseMark />
          </button>
        </div>

        <div className="lt-chat-body" ref={messagesRef}>
          {error && <div className="lt-chat-error">{error}</div>}
          <div className="chat-conduct-inline"><ChatConductNotice /></div>
          {loading && !messages.length ? (
            <div className="lt-chat-empty">Kraunama...</div>
          ) : messages.length ? (
            messages.map((message) => {
              const mine = message.sender_id === user?.id;
              return (
                <div className={`lt-chat-message ${mine ? "mine" : ""}`} key={message.id}>
                  <div className="lt-chat-message-head">
                    <div className="lt-chat-message-sender">
                      <b>{message.sender_name || (mine ? "Jūs" : "Vartotojas")}</b>
                      <span className="lt-chat-role">
                        {message.sender_role === "worker"
                          ? "Darbuotojas"
                          : message.sender_role === "employer"
                            ? "Darbdavys"
                            : message.sender_role === "admin"
                              ? "Administratorius"
                              : "Pokalbis"}
                      </span>
                    </div>
                    <time>
                      {new Date(message.created_at).toLocaleString("lt-LT", {
                        dateStyle: "short",
                        timeStyle: "short",
                      })}
                    </time>
                  </div>
                  <p>{message.body}</p>
                </div>
              );
            })
          ) : (
            <div className="lt-chat-empty">Žinučių dar nėra. Galite pradėti aptarimą.</div>
          )}
        </div>

        <form className="lt-chat-form" onSubmit={sendMessage}>
          <textarea
            value={textValue}
            onChange={(e) => setTextValue(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent?.isComposing) {
                e.preventDefault();
                if (!sending && textValue.trim()) sendMessage(e);
              }
            }}
            maxLength={2000}
            placeholder="Parašykite žinutę apie pasiūlymą..."
          />
          <button disabled={sending || !textValue.trim()}>
            {sending ? "Siunčiama..." : "Siųsti"}
          </button>
        </form>
      </div>
    </div>
  );
}

function CompanyTeamChatModal({
  open,
  onClose,
  companyId,
  companyName,
  user,
  onRead = null,
}) {
  const [messages, setMessages] = useState([]);
  const [textValue, setTextValue] = useState("");
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const messagesRef = useRef(null);
  const scrollOnLoadRef = useRef(true);
  const loadedCompanyRef = useRef(null);

  useEffect(() => {
    if (!open || !companyId) return;

    scrollOnLoadRef.current = true;
    loadedCompanyRef.current = null;
    setMessages([]);
    loadMessages();
    const timer = setInterval(loadMessages, 3000);
    return () => clearInterval(timer);
  }, [open, companyId]);

  useEffect(() => {
    if (!open || loading || loadedCompanyRef.current !== companyId || !messagesRef.current) return;

    const frame = requestAnimationFrame(() => {
      if (messagesRef.current) {
        messagesRef.current.scrollTop = messagesRef.current.scrollHeight;
      }
      scrollOnLoadRef.current = false;
    });
    return () => cancelAnimationFrame(frame);
  }, [open, loading, messages, companyId]);

  async function loadMessages() {
    if (loadedCompanyRef.current !== companyId) setLoading(true);
    setError("");

    try {
      const result = await supabase.rpc("get_company_team_messages", {
        p_company_id: companyId,
      });

      if (result.error) throw result.error;
      loadedCompanyRef.current = companyId;
      setMessages(result.data || []);

      const readResult = await supabase.rpc("mark_company_team_chat_read", {
        p_company_id: companyId,
      });

      if (readResult.error) throw readResult.error;
      onRead?.();
    } catch (err) {
      setError(err?.message || "Nepavyko įkelti vadovų pokalbio.");
    } finally {
      setLoading(false);
    }
  }

  async function sendMessage(e) {
    e.preventDefault();

    const body = textValue.trim();
    if (!body || sending || !companyId) return;

    setSending(true);
    setError("");

    try {
      const result = await supabase.rpc("send_company_team_message", {
        p_company_id: companyId,
        p_body: body,
      });

      if (result.error) throw result.error;

      setTextValue("");
      scrollOnLoadRef.current = true;
      await loadMessages();
    } catch (err) {
      setError(err?.message || "Nepavyko išsiųsti žinutės.");
    } finally {
      setSending(false);
    }
  }

  if (!open) return null;

  return (
    <div
      className="ctc-overlay"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget && !sending) onClose();
      }}
    >
      <div className="ctc-modal">
        <style>{`
          .ctc-overlay{position:fixed;inset:0;z-index:9600;background:rgba(16,36,56,.62);display:grid;place-items:center;padding:20px;backdrop-filter:blur(2px)}
          .ctc-modal{width:min(720px,100%);max-height:calc(100vh - 40px);display:grid;grid-template-rows:auto auto minmax(180px,1fr) auto;overflow:hidden;background:#fff;border-radius:20px;box-shadow:0 28px 90px rgba(16,36,56,.3);padding:22px;color:#102438}
          .ctc-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:14px}
          .ctc-head h2{margin:6px 0 0;font-family:Manrope,Inter,sans-serif;font-size:24px;line-height:1.2}
          .ctc-head p{margin:6px 0 0;color:#6c7a88;font-size:13px;line-height:1.45}
          .ctc-close{width:42px;height:42px;border:0;border-radius:12px;background:#f2f5f7;color:#102438;font-size:21px;cursor:pointer;display:grid;place-items:center;flex:0 0 auto}
          .ctc-error{background:#fff0ec;color:#b64d2a;border-radius:10px;padding:10px 12px;font-size:12px;margin-bottom:12px}
          .ctc-messages{display:grid;align-content:start;justify-items:start;gap:10px;min-height:220px;max-height:420px;overflow:auto;padding:18px 4px 14px;background:#f8fafb;border:1px solid #e8eef2;border-radius:16px}
          .ctc-empty{justify-self:stretch;text-align:center;color:#7a8996;padding:42px 14px;font-size:13px}
          .ctc-message{width:fit-content;max-width:min(84%,560px);padding:11px 13px;border-radius:14px 14px 14px 5px;background:#fff;border:1px solid #dfe7ec;box-shadow:0 2px 8px rgba(16,36,56,.04)}
          .ctc-message.mine{justify-self:end;background:#fff6ee;border-color:#f3d4b7;border-radius:14px 14px 5px 14px}
          .ctc-message b{display:block;font-size:12px;margin-bottom:5px}.ctc-role{font-weight:600;color:#7a8996}
          .ctc-message p{margin:0;white-space:pre-wrap;line-height:1.45;overflow-wrap:anywhere}.ctc-message time{display:block;margin-top:7px;color:#8a98a6;font-size:10px}
          .ctc-form{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:stretch;gap:10px;border-top:1px solid #e4ebf0;padding-top:14px;margin-top:14px}
          .ctc-form textarea{width:100%;min-height:54px;max-height:130px;resize:vertical;border:1px solid #d7e0e7;border-radius:12px;padding:11px 12px;font:inherit;line-height:1.4;outline:none}.ctc-form textarea:focus{border-color:#f08a28;box-shadow:0 0 0 3px rgba(240,138,40,.12)}
          .ctc-form button{min-height:54px;border:0;border-radius:11px;background:#f08a28;color:#fff;padding:0 18px;font:inherit;font-weight:800;cursor:pointer}.ctc-form button:disabled{opacity:.55;cursor:not-allowed}
          @media(max-width:620px){.ctc-overlay{padding:10px}.ctc-modal{width:calc(100vw - 20px);max-height:calc(100vh - 20px);padding:17px;border-radius:16px}.ctc-head h2{font-size:21px}.ctc-message{max-width:92%}.ctc-form{grid-template-columns:1fr}.ctc-form button{min-height:44px}}
        `}</style>

        <div className="ctc-head">
          <div>
            <div className="eyebrow">BUSINESS PRO · VADOVŲ POKALBIS</div>
            <h2>{companyName || "Įmonės komanda"}</h2>
            <p>
              Vidinis pokalbis tik jūsų įmonės Savininkui, Vadovams ir
              Vadybininkams.
            </p>
          </div>

          <button
            className="ctc-close"
            type="button"
            disabled={sending}
            onClick={onClose}
            aria-label="Uždaryti"
          >
            <CloseMark />
          </button>
        </div>

        {error && <div className="ctc-error">{error}</div>}

        <ChatConductNotice />

        <div className="ctc-messages" ref={messagesRef}>
          {loading && !messages.length ? (
            <div className="ctc-empty">Kraunamas vadovų pokalbis...</div>
          ) : messages.length ? (
            messages.map((message) => (
              <div
                className={
                  message.sender_id === user.id
                    ? "ctc-message mine"
                    : "ctc-message"
                }
                key={message.id}
              >
                <b>{message.sender_label || "Komandos narys"}</b>
                <p>{message.body}</p>
                <time>
                  {new Date(message.created_at).toLocaleString("lt-LT", {
                    dateStyle: "short",
                    timeStyle: "short",
                  })}
                </time>
              </div>
            ))
          ) : (
            <div className="ctc-empty">
              Vadovų pokalbis dar tuščias. Parašykite pirmą žinutę.
            </div>
          )}
        </div>

        <form className="ctc-form" onSubmit={sendMessage}>
          <textarea
            value={textValue}
            onChange={(e) => setTextValue(e.target.value)}
            onKeyDown={(e) => {
              if (
                e.key === "Enter" &&
                !e.shiftKey &&
                !e.nativeEvent?.isComposing
              ) {
                e.preventDefault();
                if (!sending && textValue.trim()) {
                  sendMessage(e);
                }
              }
            }}
            maxLength={2000}
            placeholder="Žinutė įmonės komandai..."
          />
          <button disabled={sending || !textValue.trim()}>
            {sending ? "Siunčiama..." : "Siųsti"}
          </button>
        </form>
      </div>
    </div>
  );
}

function WorkerProfileModal({
  worker,
  jobId,
  canViewWorkerMetrics = false,
  onClose,
}) {
  const [ratingReviews, setRatingReviews] = useState([]);
  const [ratingReviewsLoading, setRatingReviewsLoading] = useState(false);
  const [contactPhone, setContactPhone] = useState("");
  const [contactLoading, setContactLoading] = useState(false);
  const [contactError, setContactError] = useState("");
  const [phoneCopied, setPhoneCopied] = useState(false);

  useEffect(() => {
    if (!worker?.id) {
      setRatingReviews([]);
      setRatingReviewsLoading(false);
      return;
    }

    let cancelled = false;

    async function loadRatingReviews() {
      setRatingReviewsLoading(true);

      const result = await supabase.rpc("get_worker_recent_ratings", {
        p_worker_id: worker.id,
        p_limit: 3,
      });

      if (!cancelled) {
        setRatingReviews(result.error ? [] : result.data || []);
        setRatingReviewsLoading(false);
      }
    }

    loadRatingReviews();

    return () => {
      cancelled = true;
    };
  }, [worker?.id]);

  useEffect(() => {
    if (!worker?.id || !jobId) {
      setContactPhone("");
      setContactError("");
      return;
    }

    let cancelled = false;

    async function loadContact() {
      setContactLoading(true);
      setContactError("");

      try {
        const result = await supabase.rpc("get_worker_contact", {
          p_worker_id: worker.id,
          p_job_id: jobId,
        });

        if (result.error) throw result.error;

        if (!cancelled) {
          setContactPhone(result.data?.[0]?.phone || "");
        }
      } catch (err) {
        if (!cancelled) {
          setContactPhone("");
          setContactError(
            err?.message || "Nepavyko įkelti darbuotojo telefono numerio."
          );
        }
      } finally {
        if (!cancelled) setContactLoading(false);
      }
    }

    loadContact();

    return () => {
      cancelled = true;
    };
  }, [worker?.id, jobId]);

  async function copyWorkerPhone() {
    if (!contactPhone) return;

    try {
      await navigator.clipboard.writeText(contactPhone);
      setPhoneCopied(true);
      window.setTimeout(() => setPhoneCopied(false), 1800);
    } catch {
      setContactError("Nepavyko nukopijuoti telefono numerio.");
    }
  }

  if (!worker) return null;

  const stats = worker.publicStats || {};
  const monthMinutes = Number(stats.monthWorkedMinutes || 0);
  const reviewAverage = ratingReviews.length
    ? ratingReviews.reduce((sum, review) => sum + Number(review.score || 0), 0) / ratingReviews.length
    : null;
  const rawRatingAverage = stats.ratingAverage ?? worker.ratingAverage ?? null;
  const rawRatingCount = Number(stats.ratingCount ?? worker.ratingCount ?? 0);
  const ratingCount = rawRatingCount > 0 ? rawRatingCount : ratingReviews.length;
  const ratingAverage =
    rawRatingAverage === null || rawRatingAverage === undefined
      ? reviewAverage
      : Number(rawRatingAverage);
  const attendanceRate =
    Number(stats.attendanceRate ?? worker.attendanceRate ?? 100);
  const noShows =
    Number(stats.noShowCount ?? worker.noShowCount ?? 0);
  const earlyLeaves =
    Number(
      stats.unexcusedEarlyLeaveCount ??
        worker.unexcusedEarlyLeaveCount ??
        0
    );

  return (
    <div
      className="rs-modal-overlay"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="rs-modal-card worker-profile-modal">
        <style>{`
          .rs-modal-overlay{position:fixed;inset:0;background:rgba(16,36,56,.62);z-index:2000;display:grid;place-items:center;padding:20px}
          .worker-profile-modal{width:min(700px,100%);max-height:calc(100vh - 40px);overflow:hidden;background:#fff;border:1px solid rgba(16,36,56,.08);border-radius:20px;box-shadow:0 26px 80px rgba(16,36,56,.25);padding:0;color:#102438}
          .worker-profile-modal-scroll{max-height:calc(100vh - 40px);overflow:auto;padding:22px;box-sizing:border-box;scrollbar-gutter:stable}
          .rs-modal-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:18px}
          .rs-modal-head h2{margin:0;font-family:Manrope,Inter,sans-serif;font-size:22px}.rs-close{border:0;background:#f1f4f6;border-radius:9px;width:38px;height:38px;font-size:20px;cursor:pointer}
          .rs-profile-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
          .rs-profile-stat{background:#f6f8fa;border:1px solid #e4ebf0;border-radius:12px;padding:13px}
          .rs-profile-stat span{display:block;font-size:11px;color:#6c7a88;margin-bottom:5px;line-height:1.3}.rs-profile-stat b{font-family:Manrope,Inter,sans-serif;font-size:18px}
          .rs-profile-phone{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}
          .rs-profile-phone button{border:1px solid #dbe4ea;background:#fff;color:#102438;border-radius:8px;padding:6px 8px;font:inherit;font-size:10px;font-weight:800;cursor:pointer}
          .rs-profile-contact-error{margin-top:6px;font-size:11px;color:#b64d2a}
          .rs-profile-plan-lock{grid-column:1/-1;border:1px dashed #d7e0e7;background:#f8fafb;border-radius:12px;padding:13px 14px;color:#526374;font-size:12px;line-height:1.5}
          .rs-profile-plan-lock b{display:block;color:#102438;font-size:13px;margin-bottom:3px}
          .rs-profile-section{margin-top:18px}.rs-profile-section> b{font-family:Manrope,Inter,sans-serif}
          .rs-review-list{display:grid;gap:10px;margin-top:10px}.rs-review{border:1px solid #e4ebf0;border-radius:12px;padding:13px;background:#f8fafb}.rs-review-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:7px}.rs-review-score{font-family:Manrope,Inter,sans-serif;font-size:17px;font-weight:800}.rs-review-date{font-size:11px;color:#8a98a6}.rs-review p{margin:0;color:#4f6070;line-height:1.5;white-space:pre-wrap}
          @media(max-width:620px){.worker-profile-modal{border-radius:16px}.worker-profile-modal-scroll{max-height:calc(100vh - 20px);padding:17px}.rs-profile-grid{grid-template-columns:repeat(2,1fr)}}
          @media(max-width:420px){.rs-profile-grid{grid-template-columns:1fr}}
        `}</style>

        <div className="worker-profile-modal-scroll">
        <div className="rs-modal-head">
          <div style={{ display: "flex", gap: 13, alignItems: "center" }}>
            <div
              style={{
                width: 50,
                height: 50,
                borderRadius: "50%",
                background: "#102438",
                color: "#fff",
                display: "grid",
                placeItems: "center",
                fontWeight: 800,
                overflow: "hidden",
                flex: "0 0 50px",
              }}
            >
              {worker.avatarUrl ? (
                <img
                  src={worker.avatarUrl}
                  alt={worker.name}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                    display: "block",
                  }}
                />
              ) : (
                worker.initials
              )}
            </div>
            <div>
              <div className="eyebrow">DARBUOTOJO PROFILIS</div>
              <h2>{worker.name}</h2>
            </div>
          </div>
          <button className="rs-close" onClick={onClose}><CloseMark /></button>
        </div>

        <div className="rs-profile-grid">
          <div className="rs-profile-stat">
            <span>Miestas</span>
            <b>{worker.city || "—"}</b>
          </div>

          <div className="rs-profile-stat">
            <span>Telefonas</span>
            {contactLoading ? (
              <b>...</b>
            ) : contactPhone ? (
              <div className="rs-profile-phone">
                <b>{contactPhone}</b>
                <button type="button" onClick={copyWorkerPhone}>
                  {phoneCopied ? "Nukopijuota" : "Kopijuoti"}
                </button>
              </div>
            ) : (
              <b>—</b>
            )}
            {contactError && (
              <div className="rs-profile-contact-error">{contactError}</div>
            )}
          </div>

          <div className="rs-profile-stat">
            <span>Patirtis</span>
            <b>{Number(worker.yearsExperience || 0)} m.</b>
          </div>
          <div className="rs-profile-stat">
            <span>Dirbta šį mėnesį</span>
            <b>{Number(stats.monthWorkedDays || 0)} d.</b>
          </div>
          <div className="rs-profile-stat">
            <span>Valandų šį mėnesį</span>
            <b>{formatWorkedMinutes(monthMinutes)}</b>
          </div>
          <div className="rs-profile-stat">
            <span>Darbų šį mėnesį</span>
            <b>{Number(stats.monthJobs || 0)}</b>
          </div>
          <div className="rs-profile-stat">
            <span>Aktyvūs darbai</span>
            <b>{Number(stats.activeJobs || 0)}</b>
          </div>
          <div className="rs-profile-stat">
            <span>Darbdavio atšaukti</span>
            <b>{Number(stats.cancelledByEmployer || 0)}</b>
          </div>
          {canViewWorkerMetrics ? (
            <>
              <div className="rs-profile-stat">
                <span>Atvykimo patikimumas</span>
                <b>{Math.round(attendanceRate)}%</b>
              </div>
              <div className="rs-profile-stat">
                <span>Darbdavių įvertinimas</span>
                <b>
                  {ratingAverage === null || ratingAverage === undefined
                    ? "—"
                    : `${Number(ratingAverage).toFixed(1)} / 10`}
                </b>
                <span style={{ marginTop: 4, marginBottom: 0 }}>
                  {ratingCount ? `${ratingCount} vert.` : "Dar nėra vertinimų"}
                </span>
              </div>
              <div className="rs-profile-stat">
                <span>Neatvykimai</span>
                <b>{noShows}</b>
              </div>
              <div className="rs-profile-stat">
                <span>Nepagrįsti ankstyvi išėjimai</span>
                <b>{earlyLeaves}</b>
              </div>
            </>
          ) : (
            <div className="rs-profile-plan-lock">
              <b>Patikimumas ir įvertinimai · Business</b>
              Šie darbuotojo rodikliai prieinami Business ir Business Pro
              planuose.
            </div>
          )}
        </div>

        {worker.hasDrivingLicenseB && (
          <div className="rs-profile-section">
            <b>Vairuotojo pažymėjimas</b>
            <p style={{ margin: "6px 0 0", color: "#6c7a88" }}>
              Turi B kategoriją
            </p>
          </div>
        )}

        <div className="rs-profile-section">
          <b>Patirtis</b>
          <p style={{ color: "#526374", lineHeight: 1.6, whiteSpace: "pre-wrap", margin: "8px 0 0" }}>
            {worker.shortBio?.trim() || (Number(worker.yearsExperience || 0) > 0
              ? `Profilyje nurodyta ${Number(worker.yearsExperience)} m. patirtis. Išsamesnio aprašymo darbuotojas dar nepateikė.`
              : "Darbuotojas dar nepateikė savo patirties aprašymo.")}
          </p>
        </div>

        <div className="rs-profile-section">
          <b>Paskutiniai darbdavių įvertinimai</b>
          <p style={{ margin: "5px 0 0", color: "#7a8996", fontSize: 12 }}>
            Rodomi iki 3 naujausių darbdavių įvertinimų.
          </p>

          {ratingReviewsLoading ? (
            <div style={{ marginTop: 10, color: "#6c7a88" }}>
              Kraunami įvertinimai...
            </div>
          ) : ratingReviews.length ? (
            <div className="rs-review-list">
              {ratingReviews.map((review) => (
                <div className="rs-review" key={review.id}>
                  <div className="rs-review-head">
                    <span className="rs-review-score">
                      {review.score} / 10
                    </span>
                    <span className="rs-review-date">
                      {new Date(review.created_at).toLocaleDateString("lt-LT")}
                    </span>
                  </div>

                  {review.comment?.trim() && <p>{review.comment}</p>}
                </div>
              ))}
            </div>
          ) : (
            <div style={{ marginTop: 10, color: "#6c7a88" }}>
              Dar nėra darbdavių įvertinimų.
            </div>
          )}
        </div>
        </div>
      </div>
    </div>
  );
}

